package com.procurement.rfq.controller;import com.procurement.common.response.*;import com.procurement.rfq.dto.request.*;import com.procurement.rfq.dto.response.*;import com.procurement.rfq.entity.*;import com.procurement.rfq.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController@RequestMapping("/api/rfqs")public class RfqController{private final RfqService service;private final RfqVendorService vendors;public RfqController(RfqService s,RfqVendorService v){service=s;vendors=v;}private Pageable p(int page,int size,String sort,String direction){return PageRequest.of(page,size,Sort.by(Sort.Direction.fromString(direction),sort));}@PostMapping public ResponseEntity<ApiResponse<RfqResponse>>create(@Valid@RequestBody RfqRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("RFQ generated",service.generate(r)));}@PostMapping("/{id}/generate")public ResponseEntity<ApiResponse<RfqResponse>>generate(@PathVariable Long id,@Valid@RequestBody RfqRequest r){var x=new RfqRequest(id,r.closingDate(),r.quotationOpeningDate(),r.currency(),r.remarks());return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("RFQ generated",service.generate(x)));}@GetMapping public ApiResponse<PageResponse<RfqResponse>>search(@RequestParam(required=false)String keyword,@RequestParam(required=false)RfqStatus status,@RequestParam(required=false)Long departmentId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="createdAt")String sort,@RequestParam(defaultValue="desc")String direction){return ApiResponse.success(service.search(keyword,status,departmentId,p(page,size,sort,direction)));}@GetMapping("/{id}")public ApiResponse<RfqResponse>get(@PathVariable Long id){return ApiResponse.success(service.get(id));}@PutMapping("/{id}")public ApiResponse<RfqResponse>update(@PathVariable Long id,@Valid@RequestBody RfqRequest r){return ApiResponse.success("RFQ updated",service.update(id,r));}@DeleteMapping("/{id}")public ResponseEntity<Void>delete(@PathVariable Long id){service.delete(id);return ResponseEntity.noContent().build();}@PostMapping("/{id}/open")public ApiResponse<RfqResponse>open(@PathVariable Long id){return ApiResponse.success("RFQ opened",service.open(id));}@PostMapping("/{id}/close")public ApiResponse<RfqResponse>close(@PathVariable Long id){return ApiResponse.success("RFQ closed",service.close(id));}@PostMapping("/{id}/cancel")public ApiResponse<RfqResponse>cancel(@PathVariable Long id){return ApiResponse.success("RFQ cancelled",service.cancel(id));}@PostMapping("/{id}/vendors")public ResponseEntity<ApiResponse<RfqVendorResponse>>invite(@PathVariable Long id,@Valid@RequestBody RfqVendorRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Vendor invited",vendors.invite(id,r)));}@DeleteMapping("/{id}/vendors/{vendorId}")public ResponseEntity<Void>remove(@PathVariable Long id,@PathVariable Long vendorId){vendors.remove(id,vendorId);return ResponseEntity.noContent().build();}@GetMapping("/{id}/vendors")public ApiResponse<PageResponse<RfqVendorResponse>>rfqVendors(@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(vendors.search(id,null,p(page,size,"invitationDate","desc")));}}
